exercises.solution:
def share(part: float, total: float) -> float | None:
    """part / total, or None when total is 0."""
    if total == 0:
        return None
    return part / total


def test_share_basic() -> None:
    assert share(1, 4) == 0.25


def test_share_zero_total() -> None:
    assert share(3, 0) is None

